{
  "unit": 48,
  "font": "sans",
  "caption": "Fig. 5.1",
  "points": {
    "EaBot": {"graph": [5.5, 0]},
    "EaTop": {"graph": [5.5, 10.5]},
    "P1": {"graph": [1.8, 10]},
    "P2": {"graph": [3, 6]}
  },
  "elements": [
    {"type": "axes", "x": {"min": 0, "max": 9.5, "step": 1, "label": "kinetic energy", "numbers": false}, "y": {"min": 0, "max": 11.5, "step": 1, "label": "number of molecules", "numbers": false}, "mode": "cross"},
    {"type": "curve", "points": [[0, 0], [0.6, 3], [1.2, 8], [1.8, 10], [2.4, 8], [3.2, 4], [4.2, 1.3], [5.5, 0.3], [7, 0.05], [9, 0]], "monotone": true, "style": "solid", "weight": "thick"},
    {"type": "curve", "points": [[0, 0], [1, 0.8], [2, 3], [3, 6], [4, 5], [5, 3], [6, 1.6], [7, 0.7], [8, 0.2], [9, 0.05]], "monotone": true, "style": "dashed", "weight": "thick"},
    {"type": "segment", "from": "EaBot", "to": "EaTop", "style": "dashed", "weight": "thin", "label": {"text": "E_{a}", "side": "right", "pos": 0.85}},
    {"type": "callout", "target": "P1", "text": "T_{1}", "dir": "ne", "dist": 1},
    {"type": "callout", "target": "P2", "text": "T_{2}", "dir": "ne", "dist": 1}
  ]
}
